let lastStat='';function pushCode(){if(!FB||!S.code||!S.nick)return;const k=S.code+'|'+S.nick;if(S.cs===k)return;const{fs,db}=FB;fs.setDoc(fs.doc(db,'codes',FB.pid),{c:S.code,n:S.nick.slice(0,12),at:Date.now()}).then(()=>{S.cs=k;lsSet(LS,S)}).catch(()=>{})}
