const getW=id=>{if(/^g:/.test(String(id))){const[l,i]=String(id).slice(2).split('-'),g=window.HG.GX&&window.HG.GX[l]&&window.HG.GX[l][+i];return g?{id,en:g[0],ko:g[1],ex:g[2]||'',exk:g[3]||'',t:'g'}:null}if(/^[xk]:/.test(String(id))){const x=S.xi&&S.xi[id];return x?{id,en:x.en,ko:x.ko,t:String(id)[0]}:null}const[l,i]=String(id).split('-');const w=W[l]&&W[l][+i];return w?{id,en:w[0],ko:w[1],use:w[2],ex:w[3],exk:w[4]}:null};
