function chalQs(){let src=testItems();if(src.length<10){const L=W[S.level]||W[1],seen=new Set(src.map(x=>x.en));const r=rng(Date.now()%100000+7);for(let k=0;k<60&&src.length<10;k++){const w=L[Math.floor(r()*L.length)];if(!seen.has(w[0])){seen.add(w[0]);src.push({key:'',en:w[0],ko:w[1],st:0})}}}return buildQs(src).map(q=>({q:q.q,o:q.o,a:q.a,en:q.it.en,ko:q.it.ko}))}
let chMap={},chAt=0,chNews=[];
async function discChals(){if(!FB||K.chDisc)return;K.chDisc=1;try{const{fs,db}=FB;const sn=await fs.getDocs(fs.query(fs.collection(db,'challenges'),fs.where(`sc.${FB.pid}.at`,'>',0),fs.limit(20)));let add=0;sn.forEach(x=>{const d=x.data()||{};chMap[x.id]=d;const ex=(S.chals||[]).find(c=>c.id===x.id);if(ex&&!((+ex.at||0)>1e12)){ex.at=d.by===FB.pid?(+d.at||Date.now()):((d.sc&&d.sc[FB.pid]&&+d.sc[FB.pid].at)||Date.now());add++}if(!ex){addChal(x.id,d.by===FB.pid?{mine:1,seen:Date.now(),at:+d.at||0}:{from:String(d.nick||''),at:(d.sc&&d.sc[FB.pid]&&+d.sc[FB.pid].at)||0});add++}});if(add){S.chals.sort((a,b)=>(+a.at||0)-(+b.at||0));save();render()}}catch(e){console.warn('chal disc',e)}}
async function loadChals(force){discChals();if(!FB||!S.chals||!S.chals.length)return;if(!force&&Date.now()-chAt<60000)return;chAt=Date.now();const L=S.chals.slice(-10),{fs,db}=FB;const res=await Promise.all(L.map(c=>fs.getDoc(fs.doc(db,'challenges',c.id)).then(x=>x.exists()?x.data():null).catch(()=>null)));const nw=[];L.forEach((c,i)=>{const d=res[i];if(!d)return;chMap[c.id]=d;const sc=d.sc||{},others=Object.entries(sc).filter(([p])=>p!==FB.pid).map(([,v])=>v);if(c.mine){others.filter(v=>(+v.at||0)>(+c.seen||0)).forEach(v=>nw.push(String(v.n||'친구')));const me=sc[FB.pid];if(me&&others.length&&others.every(v=>(v.s|0)<me.s)){S.flags=S.flags||{};S.flags.win=1}}});chNews=nw;checkBadges();render()}
function chalSeen(){if(!chNews.length)return;const t=Date.now();(S.chals||[]).forEach(c=>{if(c.mine)c.seen=t});chNews=[];save()}
function chalBar(){if(!chNews.length)return '';const u=[...new Set(chNews)];return `<div class="pokebar chbar"><div><b>⚔️ ${esc(u.slice(0,3).join(', '))}${u.length>3?` 외 ${u.length-3}명`:''}</b>님이 내 도전장에 응했어요!</div><button class="btn sm" data-act="chgo">결과 보기</button></div>`}
function chalListHTML(){const hl=K.hl||[];const L=(S.chals||[]).slice(-10).reverse().sort((a,b)=>hl.includes(b.id)-hl.includes(a.id));if(!L.length)return '';return `<section><h2>내 도전장</h2><p class="sub">보내고 받은 도전장이 최근 순서로 모여요. 친구가 풀면 점수가 바로 올라와요.</p>${L.map(c=>{const d=chMap[c.id];if(!d)return `<div class="card note">도전장 불러오는 중…</div>`;const sc=d.sc||{},me=FB&&sc[FB.pid],others=Object.entries(sc).filter(([p])=>!FB||p!==FB.pid).map(([,v])=>({n:String(v.n||'친구'),s:v.s|0})).sort((a,b)=>b.s-a.s),tot=(d.qs||[]).length||10,gk=d.gk,sf=v=>gk?`${v}점`:`${v} / ${tot}`,gt=gk?` <span class="glv">${gk==='rain'?'🌧️':'⚡'} ${GN[gk]}</span>`:'';
if(c.mine){const best=others[0];const res=!others.length?'<span class="bdg no">아직 아무도 안 풀었어요</span>':me&&others.every(o=>o.s<me.s)?'<span class="bdg ok">내가 1등 🏆</span>':me&&best&&best.s>me.s?`<span class="bdg no">${esc(best.n)}님이 이겼어요</span>`:'<span class="bdg mid">비겼어요</span>';return `<div class="card chl${hl.includes(c.id)?' new':''}"><div class="wrow"><b class="grow">${hl.includes(c.id)?'<span class="newt">NEW</span> ':''}내가 보낸 도전장${gt}</b><span class="note">${md(new Date(+c.at||Date.now()).toLocaleDateString('sv'))} 보냄</span></div><div style="margin:6px 0">${res}</div><div class="wrow"><span class="grow">나</span><b>${me?sf(me.s):'-'}</b></div>${others.map(o=>`<div class="wrow"><span class="grow">${esc(o.n)}</span><b>${sf(o.s)}</b></div>`).join('')}<div class="row"><button class="btn ghost sm" data-act="chresend" data-id="${esc(c.id)}">다른 친구에게도 보내기</button></div></div>`}
const host=d.by&&sc[d.by];const res=!me?'<span class="bdg no">아직 안 풀었어요</span>':!host?'':me.s>host.s?'<span class="bdg ok">내가 이겼어요 🏆</span>':me.s<host.s?'<span class="bdg no">졌어요</span>':'<span class="bdg mid">비겼어요</span>';return `<div class="card chl"><div class="wrow"><b class="grow">${esc(d.nick||c.from||'친구')}님의 도전장${gt}</b><span class="note">${md(new Date(+c.at||Date.now()).toLocaleDateString('sv'))} 받음</span></div><div style="margin:6px 0">${res}</div><div class="wrow"><span class="grow">나</span><b>${me?sf(me.s):'-'}</b></div>${host?`<div class="wrow"><span class="grow">${esc(d.nick||'친구')}</span><b>${sf(host.s)}</b></div>`:''}${others.filter(o=>!host||o.n!==String(host.n||'')).length?`<p class="note" style="margin:6px 0 0">다른 참가자 ${others.length-(host?1:0)}명</p>`:''}${!me||gk?`<div class="row"><button class="btn ${me?'ghost ':''}sm" data-act="chplay" data-id="${esc(c.id)}">${me?'다시 도전하기':'도전하기'}</button></div>`:''}</div>`}).join('')}</section>`}
async function chalShareId(id){const d=chMap[id],me=d&&FB&&d.sc&&d.sc[FB.pid];const url=inviteLink()+'?c='+id,text=d&&d.gk?`🎮 ${S.nick}의 ${GN[d.gk]||'게임'} 도전장!${me?` 나는 ${me.s}점.`:''} 넘길 수 있어?`:`⚔️ ${S.nick}의 영어 단어 도전장!${me?` 나는 ${me.s}/${(d&&d.qs||[]).length||10}점.`:''} 이길 수 있어?`;try{if(navigator.share){await navigator.share({title:'홍글리쉬 도전장',text,url});return}}catch(e){if(e&&e.name==='AbortError')return}try{await navigator.clipboard.writeText(text+' '+url);toast('도전장 링크를 복사했어요. 카톡에 붙여 넣어 보내세요.')}catch(e){toast(url)}}
