async function chalShare(){if(!T||!T.cid)return;const url=inviteLink()+'?c='+T.cid,text=`⚔️ ${S.nick}의 영어 단어 도전장! 나는 ${T.score}/${T.qs.length}점. 이길 수 있어?`;try{if(navigator.share){await navigator.share({title:'홍글리쉬 도전장',text,url});return}}catch(e){if(e&&e.name==='AbortError')return}try{await navigator.clipboard.writeText(text+' '+url);toast('도전장 링크를 복사했어요. 카톡에 붙여 넣어 보내세요.')}catch(e){toast(url)}}
async function chalOpen(){let id=null;try{id=localStorage.getItem('honglish-chal')}catch(e){}if(!id||!FB||!S.level||!S.guided)return;try{localStorage.removeItem('honglish-chal')}catch(e){}const{fs,db}=FB;try{const sn=await fs.getDoc(fs.doc(db,'challenges',id));if(!sn.exists()){toast('도전장을 찾지 못했어요');return}const c=sn.data();chMap[id]=c;if(c.by===FB.pid)addChal(id,{mine:1,seen:Date.now(),gk:c.gk});else addChal(id,{from:String(c.nick||''),gk:c.gk});save();if(c.gk){if(c.by===FB.pid){location.hash='#duel';render();return}return gchOpen(id)}location.hash='#duel';if(c.sc&&c.sc[FB.pid]){T={kind:'chal',cid:id,from:c.nick,qs:c.qs,i:c.qs.length,score:c.sc[FB.pid].s,pick:null,done:true};K.chres=c.sc;render();return}T={kind:'chal',cid:id,from:c.nick,by:c.by,qs:(c.qs||[]).slice(0,10),i:0,score:0,pick:null};render()}catch(e){toast('도전장을 불러오지 못했어요')}}
async function chalFinish(){if(!FB||!T||!T.cid)return;const{fs,db}=FB;try{await fs.setDoc(fs.doc(db,'challenges',T.cid),{sc:{[FB.pid]:{n:S.nick.slice(0,12),s:T.score,at:Date.now()}}},{merge:true});const sn=await fs.getDoc(fs.doc(db,'challenges',T.cid));K.chres=(sn.data()||{}).sc||{};chMap[T.cid]=sn.data()||chMap[T.cid];const host=T.by&&K.chres[T.by];if(host&&T.score>host.s){S.flags=S.flags||{};S.flags.win=1;checkBadges();save()}render()}catch(e){toast('결과를 저장하지 못했어요')}}
function chalResultHTML(){if(T.kind==='chmake')return T.cid?`<div class="card"><b>도전장을 만들었어요!</b><p class="note" style="margin:4px 0 0">링크를 받은 친구가 같은 10문제를 풀면 결과가 비교돼요. 링크를 다시 열면 누가 이겼는지 볼 수 있어요.</p><div class="row"><button class="btn" data-act="chsend">도전장 다시 보내기</button></div></div>`:`<div class="card note">도전장을 만드는 중이에요…</div>`;
const r=K.chres?Object.entries(K.chres).map(([id,v])=>({id,n:String(v.n||'친구'),s:v.s|0,at:+v.at||0})).sort((a,b)=>b.s-a.s||a.at-b.at):[];const top=r[0];
return `<div class="card"><b>⚔️ ${esc(T.from||'친구')}님의 도전장 결과</b>${r.length?r.map((x,i)=>`<div class="wrow" style="margin-top:8px"><span class="grow">${i===0?'👑 ':''}${esc(x.n)}${FB&&x.id===FB.pid?' (나)':''}</span><b>${x.s} / ${T.qs.length}</b></div>`).join(''):'<p class="note">결과를 불러오는 중이에요…</p>'}${top&&FB&&top.id===FB.pid&&r.length>1?'<p style="margin:10px 0 0">🏆 내가 이겼어요!</p>':''}<div class="row"><button class="btn" data-act="chmake">나도 도전장 보내기</button></div></div>`}
/* 게임: 단어 소나기 · 60초 스피드 퀴즈 */
let G=null,gData=null,gAt=0,gBusy=false;
const GN={rain:'단어 소나기',speed:'60초 스피드 퀴즈'};
const gPool=()=>{const l=W[S.level]?S.level:1,gx=(window.HG.GX&&window.HG.GX[l])||[];return W[l].map((w,i)=>({id:l+'-'+i,en:w[0],ko:w[1]})).concat(gx.map((w,i)=>({id:'g:'+l+'-'+i,en:w[0],ko:w[1]})))};
function gMiss(w){if(!w||!w.id)return;if(G)G.miss=(G.miss||0)+1;S.gw=S.gw||{};const o=S.gw[w.id]||{n:0};o.n++;o.at=Date.now();S.gw[w.id]=o;const ks=Object.keys(S.gw);if(ks.length>200){ks.sort((a,b)=>S.gw[a].at-S.gw[b].at).slice(0,ks.length-200).forEach(k=>delete S.gw[k])}}
function gReset(){const wk=weekStart(today());if(!S.gb||S.gb.wk!==wk||S.gb.lv!==S.level)S.gb={wk,lv:S.level|0,r:0,s:0}}
function gQ(){const P=gPool(),w=P[Math.floor(Math.random()*P.length)],ek=Math.random()<.5,f=ek?'ko':'en';const others=shuf(P.filter(x=>x.en!==w.en&&x.ko!==w.ko).map(x=>x[f])).filter((v,i,a)=>a.indexOf(v)===i).slice(0,3);const o=shuf([w[f]].concat(others));return{w,q:ek?w.en:w.ko,ek,o,a:o.indexOf(w[f])}}
function gDraw(){const c=G.cur,rain=G.kind==='rain';$('#app').innerHTML=`<div class="game ${G.kind}"><div class="ghead"><button class="ib" data-act="gquit" aria-label="그만하기">✕</button><b class="grow">${GN[G.kind]}</b><span class="gpill">점수 <b id="gsc">${G.score}</b></span>${rain?`<span class="gpill" id="glv">${'❤️'.repeat(G.lives)}${'🤍'.repeat(3-G.lives)}</span>`:`<span class="gpill">⏱ <b id="gtime">${Math.ceil(Math.max(0,G.end-performance.now())/1000)}</b></span>`}</div>${G.combo>1?`<div class="gcombo">🔥 ${G.combo} 콤보</div>`:'<div class="gcombo"></div>'}${rain?`<p class="note" style="text-align:center;margin:2px 0">${c.ek?'뜻을 고르세요':'영어로 고르세요'}</p><div class="arena" id="arena"><div class="drop" id="drop">${esc(c.q)}</div></div>`:`<div class="sq"><div class="tbar"><i id="tbar"></i></div><p class="note">${c.ek?'뜻을 고르세요':'영어로 고르세요'}</p><div class="sqq">${esc(c.q)}</div></div>`}<div class="gopts">${c.o.map((o,j)=>`<button class="gopt" data-act="gans" data-o="${j}">${esc(o)}</button>`).join('')}</div><div class="gfx" id="gfx">${G.fx||''}</div></div>`}
function gStart(kind){gReset();if(G&&G.raf)cancelAnimationFrame(G.raf);G={kind,on:1,score:0,combo:0,lives:3,dur:7000,end:performance.now()+60000};G.cur=gQ();G.t0=performance.now();gDraw();G.raf=requestAnimationFrame(gTick)}
function gNext(){G.cur=gQ();G.t0=performance.now();gDraw()}
function gTick(now){if(!G||!G.on)return;if(G.kind==='rain'){const ar=$('#arena'),dr=$('#drop');if(ar&&dr){const H=ar.clientHeight-dr.offsetHeight,p=(now-G.t0)/G.dur;dr.style.transform=`translateY(${Math.max(0,p*H)}px)`;if(p>=1){G.lives--;G.combo=0;gMiss(G.cur.w);G.fx=`<span class="no">놓쳤어요! ${esc(G.cur.w.ko)} = <b>${esc(G.cur.w.en)}</b></span>`;if(G.lives<=0)return gFinish();gNext()}}}else{const left=G.end-now,tb=$('#tbar'),tt=$('#gtime');if(tb)tb.style.width=Math.max(0,left/600)+'%';if(tt)tt.textContent=Math.ceil(Math.max(0,left)/1000);if(left<=0)return gFinish()}G.raf=requestAnimationFrame(gTick)}
const LVB={1:1,2:1.1,3:1.2};
function gAnswer(o){if(!G||!G.on)return;const c=G.cur;if(o===c.a){const pts=Math.round((10+Math.min(G.combo,10)*2)*(LVB[S.level|0]||1));G.score+=pts;G.combo++;if(G.kind==='rain')G.dur=Math.max(1800,G.dur*.95);G.fx=`<span class="ok">+${pts}</span>`;gNext()}else{G.combo=0;gMiss(c.w);const ans=`${esc(c.w.ko)} = <b>${esc(c.w.en)}</b>`;if(G.kind==='rain'){G.lives--;G.fx=`<span class="no">❌ ${ans}</span>`;if(G.lives<=0)return gFinish()}else{G.score=Math.max(0,G.score-5);G.fx=`<span class="no">-5 · ${ans}</span>`}gNext()}}
function gFinish(){G.on=0;cancelAnimationFrame(G.raf);if(G.kind==='speed'&&G.cur)gMiss(G.cur.w);gReset();const k=G.kind==='rain'?'r':'s',prev=S.gb[k]|0,rec=G.score>prev;if(rec){S.gb[k]=G.score;pushGame()}save();G.done=1;const gc=K.gch&&K.gch.kind===G.kind?K.gch:null;let gcr='';if(gc){gcr=G.score>gc.target?`<div class="card" style="margin:10px 0;background:var(--soft)"><b>🏆 ${esc(gc.from)}님(${gc.target}점)을 이겼어요!</b></div>`:G.score===gc.target?`<div class="card" style="margin:10px 0"><b>🤝 ${esc(gc.from)}님과 ${gc.target}점 동점이에요!</b></div>`:`<div class="card" style="margin:10px 0"><b>😢 ${esc(gc.from)}님 ${gc.target}점까지 ${gc.target-G.score}점 모자라요.</b><div class="note">다시 하기로 재도전할 수 있어요. 가장 높은 점수가 남아요.</div></div>`;gchSubmit(gc,G.score)}const missN=G.miss||0;$('#app').innerHTML=`<div class="game"><div class="gcard" style="margin:40px auto;text-align:center"><div class="gico">${rec&&G.score?'🏆':'🎮'}</div><h2>${GN[G.kind]} 끝!</h2><div style="font-size:44px;font-weight:800;margin:6px 0">${G.score}점</div><p>${rec&&G.score?'<b>이번 주 신기록!</b> 랭킹에 올라갔어요.':`이번 주 최고 기록 ${prev}점`}</p>${gcr}<p class="note">Lv.${S.level} ${LVN[S.level]} 단어로 나왔어요.${missN?` 틀리거나 못 맞힌 단어 ${missN}개는 단어장 > 게임 오답에 모아뒀어요.`:''}</p>${FB&&G.score>0&&!gc?`<div class="row"><button class="btn ghost wide" data-act="ginv">⚔️ 이 점수로 친구에게 도전장 보내기</button></div>`:''}<div class="row"><button class="btn ghost grow" data-act="gexit">게임 목록</button><button class="btn grow" data-act="gplay" data-g="${G.kind}">다시 하기</button></div></div></div>`}
async function gInvite(){if(!FB||!G||!G.score)return;const{fs,db}=FB,id=genCode().slice(0,8),me={n:S.nick.slice(0,12),s:G.score,at:Date.now()},kind=G.kind,score=G.score;try{await fs.setDoc(fs.doc(db,'challenges',id),{by:FB.pid,nick:S.nick.slice(0,12),lv:S.level|0,at:Date.now(),qs:[],gk:kind,sc:{[FB.pid]:me}});addChal(id,{mine:1,seen:Date.now(),gk:kind});chMap[id]={by:FB.pid,nick:S.nick,qs:[],gk:kind,sc:{[FB.pid]:me}};S.flags=S.flags||{};S.flags.chal=1;checkBadges();save();chalShareId(id)}catch(e){toast('도전장을 만들지 못했어요. 인터넷을 확인해 주세요.')}}
function gchSubmit(gc,score){if(!FB||!gc)return;if(score<=(gc.my|0)&&gc.my!=null)return;gc.my=score;const{fs,db}=FB,e={n:S.nick.slice(0,12),s:score,at:Date.now()};const d=chMap[gc.id];if(d){d.sc=d.sc||{};d.sc[FB.pid]=e}if(gc.by&&score>gc.target){S.flags=S.flags||{};S.flags.win=1;checkBadges()}save();fs.setDoc(fs.doc(db,'challenges',gc.id),{sc:{[FB.pid]:e}},{merge:true}).catch(()=>toast('결과를 저장하지 못했어요'))}
function gchOpen(id){const d=chMap[id];if(!d||!d.gk)return;const host=d.sc&&d.sc[d.by],mine=FB&&d.sc&&d.sc[FB.pid];K.gch={id,kind:d.gk,from:String(d.nick||'친구'),by:d.by,target:host?host.s|0:0,my:mine?mine.s|0:null};T=null;location.hash='#game';window.scrollTo(0,0);render()}
function gchBanner(){const g=K.gch;if(!g)return '';return `<div class="card chl new" style="margin-top:4px"><div class="wrow"><b class="grow">⚔️ ${esc(g.from)}님의 ${GN[g.kind]} 도전장</b><button class="ib" data-act="gchx" aria-label="닫기">✕</button></div><p style="margin:6px 0">${esc(g.from)}님 점수 <b>${g.target}점</b>을 넘겨보세요!${g.my!=null?` 내 최고 <b>${g.my}점</b>${g.my>g.target?' 🏆':''}`:''}</p><div class="note">내 레벨 단어로 나오고 레벨 보너스도 그대로 붙어요.</div><div class="row"><button class="btn wide" data-act="gplay" data-g="${g.kind}">도전하기</button></div></div>`}
/* 단체전 (실시간, 최대 8명) */
let RL={list:[],ok:0,un:null};
function rlSub(){if(RL.un||!FB||RM)return;const{fs,db}=FB;RL.un=fs.onSnapshot(fs.query(fs.collection(db,'rooms'),fs.orderBy('hb','desc'),fs.limit(20)),qs=>{RL.list=qs.docs.map(d=>Object.assign({id:d.id},d.data()));RL.ok=1;rlUpd()},()=>{RL.ok=1;rlUpd()});RL.tm=setInterval(rlUpd,30000)}
function rlStop(){if(RL.un){try{RL.un()}catch(e){}RL.un=null}clearInterval(RL.tm)}
function rlUpd(){const b=$('#rlist');if(b)b.innerHTML=rlHTML()}
function rlHTML(){if(!FB)return '<p class="note" style="margin:6px 0 0">서버에 연결되면 보여요</p>';if(!RL.ok)return '<p class="note" style="margin:6px 0 0">불러오는 중…</p>';const now=Date.now(),L=RL.list.filter(r=>typeof r.hb==='number'&&r.hb>now-180000&&(r.st==='wait'||r.st==='play')).sort((a,b)=>(a.st==='wait'?0:1)-(b.st==='wait'?0:1)||b.hb-a.hb);if(!L.length)return '<p class="note" style="margin:6px 0 0">지금 열린 방이 없어요. 방을 만들면 여기 떠요!</p>';return L.map(r=>{const n=Math.max(1,r.n|0),full=n>=TMAX,play=r.st==='play',me=FB&&r.host===FB.pid;return `<div class="wrow rmrow${play?' dim':''}"><span class="grow"><b>${esc(String(r.hn||'친구').slice(0,12))}</b>님의 방${me?' (내 방)':''}<div class="note">${n}/${TMAX}명 · ${play?'게임 중 · 다음 판부터 참가':'대기 중'}</div></span><button class="btn sm${play?' ghost':''}" data-act="rjoin" data-id="${esc(r.id)}" ${full?'disabled':''}>${full?'꽉 참':'들어가기'}</button></div>`}).join('')}
const TD=4500,TN=20,TMAX=8;let RM=null,TP=null,lgData=null,lgAt=0,lgBusy=false;
function trng(seed){let a=seed>>>0;return()=>{a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
function tPool(){const gx=(window.HG.GX&&window.HG.GX[2])||[];return W[2].map((w,i)=>({id:'2-'+i,en:w[0],ko:w[1]})).concat(gx.map((w,i)=>({id:'g:2-'+i,en:w[0],ko:w[1]})))}
function tQs0(seed){const R=trng(seed),P=tPool(),used=new Set(),out=[];const pick=()=>P[Math.floor(R()*P.length)];let guard=0;while(out.length<TN&&guard<5000){guard++;const w=pick();if(used.has(w.en))continue;used.add(w.en);const ek=R()<.5,f=ek?'ko':'en',o=[w[f]];let g=0;while(o.length<4&&g<300){g++;const x=pick();if(x.en===w.en||x.ko===w.ko||o.includes(x[f]))continue;o.push(x[f])}for(let i=o.length-1;i>0;i--){const j=Math.floor(R()*(i+1));[o[i],o[j]]=[o[j],o[i]]}out.push({w,ek,q:ek?w.en:w.ko,o,a:o.indexOf(w[f])})}return out}
function tQs(seed,ids){if(!Array.isArray(ids)||!ids.length)return tQs0(seed);const R=trng(seed),P=tPool(),M={};P.forEach(w=>M[w.id]=w);const L=[],used=new Set();ids.forEach(id=>{const w=M[id];if(w&&!used.has(w.en)){used.add(w.en);L.push(w)}});let g=0;while(L.length<TN&&g<5000){g++;const w=P[Math.floor(R()*P.length)];if(used.has(w.en))continue;used.add(w.en);L.push(w)}return L.slice(0,TN).map(w=>{const ek=R()<.5,f=ek?'ko':'en',o=[w[f]];let k=0;while(o.length<4&&k<300){k++;const x=P[Math.floor(R()*P.length)];if(x.en===w.en||x.ko===w.ko||o.includes(x[f]))continue;o.push(x[f])}for(let i=o.length-1;i>0;i--){const j=Math.floor(R()*(i+1));[o[i],o[j]]=[o[j],o[i]]}return{w,ek,q:ek?w.en:w.ko,o,a:o.indexOf(w[f])}})}
function tPickIds(){const P=tPool(),rc=new Set(S.tu||[]);let C=P.filter(w=>!rc.has(w.id));if(C.length<TN*3)C=P;const out=[],en=new Set();let g=0;while(out.length<TN&&g<5000){g++;const w=C[Math.floor(Math.random()*C.length)];if(en.has(w.en))continue;en.add(w.en);out.push(w.id)}return out}
function tPlayers(){if(!RM||!RM.room)return[];const rd=RM.room.rd|0;return Object.entries(RM.ps).filter(([,p])=>p&&(p.r|0)===rd&&p.r!==-1).map(([id,p])=>({id,n:String(p.n||'친구').slice(0,12),a:p.a||{},j:p.j|0})).sort((a,b)=>a.j-b.j)}
function tPlace(i){return tPlayers().map(p=>[p.id,p.a[i]]).filter(([,v])=>typeof v==='number'&&v>=0).sort((x,y)=>x[1]-y[1])}
function tScores(){const L=tPlayers(),sc={};L.forEach(p=>sc[p.id]=0);for(let i=0;i<TN;i++)tPlace(i).slice(0,3).forEach(([id],k)=>{if(id in sc)sc[id]+=[5,3,1][k]});return L.map(p=>({id:p.id,n:p.n,s:sc[p.id]})).sort((a,b)=>b.s-a.s)}
function tStop(){if(RM){try{RM.un1&&RM.un1();RM.un2&&RM.un2();RM.un3&&RM.un3();clearInterval(RM.hbt)}catch(e){}}K.tmsg='';K.tfocus=false;RM=null;if(TP){TP.on=0;cancelAnimationFrame(TP.raf)}TP=null}
function tSub(id){const{fs,db}=FB;tStop();rlStop();RM={id,room:null,ps:{}};RM.hbt=setInterval(()=>{if(RM&&RM.id===id&&RM.room&&RM.room.host===FB.pid&&!document.hidden)fs.updateDoc(fs.doc(db,'rooms',id),{hb:Date.now()}).catch(()=>{})},60000);RM.un1=fs.onSnapshot(fs.doc(db,'rooms',id),sn=>{if(!RM||RM.id!==id)return;RM.room=sn.exists()?sn.data():null;tOnRoom()},()=>{});RM.un2=fs.onSnapshot(fs.collection(db,'rooms',id,'p'),qs=>{if(!RM||RM.id!==id)return;qs.docChanges().forEach(ch=>{if(ch.type==='removed')delete RM.ps[ch.doc.id];else RM.ps[ch.doc.id]=ch.doc.data()});RM.psOk=1;tOnPlayers()},()=>{});RM.msgs=[];RM.un3=fs.onSnapshot(fs.query(fs.collection(db,'rooms',id,'m'),fs.orderBy('at'),fs.limitToLast(50)),qs=>{if(!RM||RM.id!==id)return;RM.msgs=qs.docs.map(d=>d.data());tChatUpd()},()=>{})}
const TQUICK=['ㅋㅋㅋㅋ','빨리 시작해요!','한 판 더! 🔥','👍','잠깐만요!','GG 👏'];
function tChatList(){const L=(RM&&RM.msgs)||[];return L.length?L.map(m=>{const me=FB&&m.p===FB.pid;return `<div class="cm${me?' me':''}">${me?'':`<b>${esc(String(m.n||'친구').slice(0,12))}</b>`}<span>${esc(String(m.t||'').slice(0,100))}</span></div>`}).join(''):'<p class="note" style="text-align:center;margin:8px 0">아직 대화가 없어요. 먼저 인사해 보세요 👋</p>'}
function tChatBox(){return `<div class="card tchat"><b>💬 대기방 채팅</b><div class="tmsgs" id="tmsgs">${tChatList()}</div><div class="tquick">${TQUICK.map((q,i)=>`<button class="chip" data-act="tq" data-i="${i}">${esc(q)}</button>`).join('')}</div><form id="tcf" class="tcf"><input id="tcin" maxlength="100" placeholder="메시지 보내기" autocomplete="off" value="${esc(K.tmsg||'')}"><button class="btn sm">보내기</button></form></div>`}
function tChatUpd(){const b=$('#tmsgs');if(!b)return;b.innerHTML=tChatList();b.scrollTop=b.scrollHeight}
function tSend(t){t=String(t||'').trim().slice(0,100);if(!t||!RM||!FB)return;const now=Date.now();if(K.tlast&&now-K.tlast<800)return;K.tlast=now;FB.fs.addDoc(FB.fs.collection(FB.db,'rooms',RM.id,'m'),{p:FB.pid,n:S.nick.slice(0,12),t,at:now}).catch(()=>toast('메시지를 보내지 못했어요'))}
function tChatRestore(){const b=$('#tmsgs');if(b)b.scrollTop=b.scrollHeight;if(K.tfocus){const i=$('#tcin');if(i){i.focus();try{const n=i.value.length;i.setSelectionRange(n,n)}catch(e){}}}}
function tMeIn(){const me=RM&&RM.ps[FB.pid];return !!(me&&RM.room&&(me.r|0)===(RM.room.rd|0)&&me.r!==-1)}
function tOnRoom(){if(!RM)return;const r=RM.room;if(!r){toast('방이 없어졌어요');tStop();render();return}const rd=r.rd|0;
if(r.st==='wait'){if(TP&&TP.rd!==rd){TP.on=0;cancelAnimationFrame(TP.raf);TP=null}if(RM.psOk&&!tMeIn()&&!RM.joining&&!RM.left&&tPlayers().length<TMAX){RM.joining=1;FB.fs.setDoc(FB.fs.doc(FB.db,'rooms',RM.id,'p',FB.pid),{n:S.nick.slice(0,12),j:Date.now(),r:rd,a:{}}).catch(()=>toast('방에 들어가지 못했어요')).finally(()=>{if(RM)RM.joining=0})}if(!TP)render();return}
if(r.st==='play'&&tMeIn()&&(!TP||TP.rd!==rd))return tBegin();if(!TP)render()}
function tOnPlayers(){if(!RM)return;if(RM.room&&RM.room.host===FB.pid&&RM.psOk){const c=tPlayers().length;if(c&&(RM.room.n|0)!==c&&RM.nSent!==c){RM.nSent=c;FB.fs.updateDoc(FB.fs.doc(FB.db,'rooms',RM.id),{n:c,hb:Date.now()}).catch(()=>{RM.nSent=0})}}if(RM.room&&RM.room.st==='wait'&&!tMeIn()&&!RM.joining&&!RM.left)return tOnRoom();if(TP){if(TP.on){const b=$('#tboard');if(b)b.innerHTML=tBoard()}else if(TP.fin)tFinal();return}render()}
async function tCreate(){if(!FB){toast('서버에 연결되면 할 수 있어요');return}const{fs,db}=FB,id=genCode().slice(0,6);try{await fs.setDoc(fs.doc(db,'rooms',id),{host:FB.pid,hn:S.nick.slice(0,12),st:'wait',at:Date.now(),seed:0,rd:0,n:1,hb:Date.now()});await fs.setDoc(fs.doc(db,'rooms',id,'p',FB.pid),{n:S.nick.slice(0,12),j:Date.now(),r:0,a:{}});tSub(id);location.hash='#game';render()}catch(e){toast('방을 만들지 못했어요. 인터넷을 확인해 주세요.')}}
async function tJoin(id){if(!FB)return;try{const sn=await FB.fs.getDoc(FB.fs.doc(FB.db,'rooms',id));if(!sn.exists()){toast('단체전 방을 찾지 못했어요');return}tSub(id);location.hash='#game';render()}catch(e){toast('방에 들어가지 못했어요')}}
function roomOpen(){let id=null;try{id=localStorage.getItem('honglish-room')}catch(e){}if(!id||!FB||!S.level||!S.guided)return;try{localStorage.removeItem('honglish-room')}catch(e){}tJoin(id)}
async function tInvite(){if(!RM)return;const url=inviteLink()+'?r='+RM.id,text=`👥 ${S.nick}님이 홍글리쉬 단어 소나기 단체전에 초대했어요! 지금 들어와서 같이 붙어요 (최대 8명)`;try{if(navigator.share){await navigator.share({title:'홍글리쉬 단체전',text,url});return}}catch(e){if(e&&e.name==='AbortError')return}try{await navigator.clipboard.writeText(text+' '+url);toast('초대 링크를 복사했어요. 카톡에 붙여 넣어 보내세요.')}catch(e){toast(url)}}
async function tStart(){if(!RM||!RM.room||RM.room.host!==FB.pid)return;if(tPlayers().length<2){toast('2명 이상 모이면 시작할 수 있어요');return}const{fs,db}=FB;try{await fs.updateDoc(fs.doc(db,'rooms',RM.id),{st:'play',seed:Math.floor(Math.random()*1e9),t0:fs.serverTimestamp(),q:tPickIds(),n:tPlayers().length,hb:Date.now()})}catch(e){toast('시작하지 못했어요')}}
function tAgain(){if(!RM||!RM.room||RM.room.host!==FB.pid)return;FB.fs.updateDoc(FB.fs.doc(FB.db,'rooms',RM.id),{st:'wait',rd:(RM.room.rd|0)+1,hb:Date.now()}).catch(()=>toast('다시 시작하지 못했어요'))}
function tLeave(){if(RM&&FB){RM.left=1;if(RM.room&&RM.room.host===FB.pid)FB.fs.updateDoc(FB.fs.doc(FB.db,'rooms',RM.id),{hb:0}).catch(()=>{});FB.fs.setDoc(FB.fs.doc(FB.db,'rooms',RM.id,'p',FB.pid),{r:-1},{merge:true}).catch(()=>{})}tStop();render()}
function tBegin(){const r=RM.room;const qs=tQs(r.seed|0,r.q);S.tu=(S.tu||[]).filter(id=>!qs.some(c=>c.w.id===id)).concat(qs.map(c=>c.w.id)).slice(-300);TP={on:1,rd:r.rd|0,qs,start:performance.now()+3000,i:-1,ans:{},fx:'',cd:0};TP.raf=requestAnimationFrame(tTick)}
function tBoard(){return tScores().map((x,k)=>`<span class="tb${x.id===FB.pid?' me':''}">${k+1}. ${esc(x.n)} <b>${x.s}</b></span>`).join('')}
function tDraw(){const c=TP.qs[TP.i],an=TP.ans[TP.i];$('#app').innerHTML=`<div class="game rain"><div class="ghead"><button class="ib" data-act="tquit" aria-label="나가기">✕</button><b class="grow">👥 단체전 ${TP.i+1}/${TN}</b><span class="gpill">⏱ <b id="ttime">${Math.ceil((TN*TD-(performance.now()-TP.start))/1000)}</b></span></div><div class="tboard" id="tboard">${tBoard()}</div><p class="note" style="text-align:center;margin:2px 0">${c.ek?'뜻을 고르세요':'영어로 고르세요'}</p><div class="arena" id="arena"><div class="drop" id="drop">${esc(c.q)}</div></div><div class="gopts">${c.o.map((o,j)=>`<button class="gopt${an!=null?(j===c.a?' r':j===an?' w':''):''}" data-act="tans" data-o="${j}" ${an!=null?'disabled':''}>${esc(o)}</button>`).join('')}</div><div class="gfx" id="gfx">${TP.fx||''}</div></div>`}
function tRes(i){const c=TP.qs[i],an=TP.ans[i];if(an==null){gMiss(c.w);return `<span class="no">놓쳤어요! ${esc(c.w.ko)} = <b>${esc(c.w.en)}</b></span>`}if(an!==c.a)return TP.fx;const pl=tPlace(i),k=pl.findIndex(([id])=>id===FB.pid);return k>=0&&k<3?`<span class="ok">${k+1}등! +${[5,3,1][k]}</span>`:`<span class="ok">정답! (4등 이하라 점수는 없어요)</span>`}
function tTick(now){if(!TP||!TP.on)return;const el=now-TP.start;if(el<0){const c=Math.ceil(-el/1000);if(TP.cd!==c){TP.cd=c;$('#app').innerHTML=`<div class="game"><div class="gcard" style="margin:80px auto;text-align:center"><div class="gico">👥</div><h2>단체전 시작!</h2><div style="font-size:64px;font-weight:800">${c}</div><p class="note">단어마다 가장 빨리 맞힌 1·2·3등이 5·3·1점</p></div></div>`}}else{const i=Math.floor(el/TD);if(i>=TN){if(TP.i>=0)TP.fx=tRes(TP.i);return tEnd()}if(i!==TP.i){if(TP.i>=0)TP.fx=tRes(TP.i);TP.i=i;TP.t0=TP.start+i*TD;tDraw()}const ar=$('#arena'),dr=$('#drop');if(ar&&dr){const p=Math.min(1,(now-TP.t0)/TD),H=ar.clientHeight-dr.offsetHeight;dr.style.transform=`translateY(${Math.max(0,p*H)}px)`}const tt=$('#ttime');if(tt)tt.textContent=Math.max(0,Math.ceil((TN*TD-el)/1000))}TP.raf=requestAnimationFrame(tTick)}
function tAnswer(o){if(!TP||!TP.on||TP.i<0||TP.ans[TP.i]!=null)return;const i=TP.i,c=TP.qs[i],rt=Math.max(0,Math.round(performance.now()-TP.t0)),ok=o===c.a;TP.ans[i]=o;TP.fx=ok?'<span class="ok">정답! 순위 계산 중…</span>':`<span class="no">❌ ${esc(c.w.ko)} = <b>${esc(c.w.en)}</b></span>`;if(!ok)gMiss(c.w);if(RM)RM.ps[FB.pid]=Object.assign({},RM.ps[FB.pid],{a:Object.assign({},(RM.ps[FB.pid]||{}).a,{[i]:ok?rt:-1})});FB.fs.setDoc(FB.fs.doc(FB.db,'rooms',RM.id,'p',FB.pid),{a:{[i]:ok?rt:-1}},{merge:true}).catch(()=>{});tDraw()}
function tEnd(){TP.on=0;cancelAnimationFrame(TP.raf);save();$('#app').innerHTML=`<div class="game"><div class="gcard" style="margin:80px auto;text-align:center"><div class="gico">⏱</div><h2>끝! 점수 계산 중…</h2></div></div>`;setTimeout(()=>{if(!TP)return;TP.fin=1;tFinal()},1800)}
function tFinal(){if(!TP||!RM||!RM.room)return;const sc=tScores(),k=sc.findIndex(x=>x.id===FB.pid),n=sc.length,lp=n>=2&&k>=0&&k<3?[5,3,1][k]:0,key=RM.id+':'+TP.rd;if(!TP.lg&&n>=2&&k>=0){TP.lg=1;S.lgd=S.lgd||[];if(!S.lgd.includes(key)){S.lgd=S.lgd.concat(key).slice(-30);save();const{fs,db}=FB;fs.setDoc(fs.doc(db,'leagues',weekStart(today())),{[FB.pid]:{n:S.nick.slice(0,12),p:fs.increment(lp),g:fs.increment(1),w:fs.increment(k===0?1:0),tt:titleOf(S.title).slice(0,12)}},{merge:true}).then(()=>{lgAt=0}).catch(()=>{})}}const host=RM.room.host===FB.pid;$('#app').innerHTML=`<div class="game"><div class="gcard" style="margin:24px auto;text-align:center"><div class="gico">${k===0?'🏆':'👥'}</div><h2>단체전 결과</h2><div style="text-align:left;margin:10px 0">${sc.map((x,j)=>`<div class="wrow tres${x.id===FB.pid?' me':''}"><span style="width:34px">${['🥇','🥈','🥉'][j]||(j+1)+'.'}</span><span class="grow">${esc(x.n)}${x.id===FB.pid?' (나)':''}</span><b>${x.s}점</b></div>`).join('')}</div><p>${n<2?'혼자 남아서 리그 점수는 없어요.':lp?`이번 주 단체전 리그 점수 <b>+${lp}</b>`:'3등 안에 들면 리그 점수를 받아요. 다음 판 화이팅!'}</p>${tMissHTML()}<div class="row">${host?'<button class="btn grow" data-act="tagain">한 판 더</button>':''}<button class="btn ghost grow" data-act="tleave">나가기</button></div>${host?'':'<p class="note">방장이 한 판 더를 누르면 같은 방에서 다시 시작해요.</p>'}${S.fast?'<div class="card" style="margin-top:12px;text-align:left"><b>📚 매일 공부도 해볼까요?</b><p class="note" style="margin:4px 0 8px">레벨테스트(3분)로 내 수준을 정하면 매일 단어·문장·영작·아티클이 맞춰서 나와요.</p><button class="btn ghost sm" data-act="fastlt">레벨테스트 보기</button></div>':''}<div style="text-align:left;margin-top:12px">${tChatBox()}</div></div></div>`;setTimeout(tChatRestore,0)}
function tMissHTML(){const ms=TP.qs.filter((c,i)=>TP.ans[i]==null||TP.ans[i]!==c.a);if(!ms.length)return '<p class="note">이번 판은 오답이 하나도 없어요! 👏</p>';return `<div class="card" style="text-align:left"><b>📝 이번 판 오답 ${ms.length}개</b><div class="note" style="margin:2px 0 6px">틀리거나 못 맞히고 지나간 단어예요. 단어장 > 게임 오답에 저장했어요.</div>${ms.map(c=>`<div style="padding:4px 0"><div class="wrow"><b class="grow">${esc(c.w.en)}</b><span class="note">${esc(c.w.ko)}</span></div>${(()=>{const g=getW(c.w.id);return g&&g.ex?`<div class="note" style="margin-top:1px">${esc(g.ex)} · ${esc(g.exk)}</div>`:''})()}</div>`).join('')}</div>`}
function fastCard(){return `<div class="card tip" style="border-color:var(--blue)"><b>📚 매일 공부도 같이 해요!</b><p class="note" style="margin:4px 0 10px">레벨테스트(15문제, 3분)를 보면 내 수준에 맞는 단어·문장·영작·아티클이 매일 나와요. 지금은 임시로 Lv.2예요.</p><div class="row"><button class="btn sm" data-act="fastlt">레벨테스트 보기</button></div></div>`}
function vRoom(){const r=RM.room;if(!r)return `<section><h2>👥 단체전</h2><p class="note">방을 불러오는 중…</p><div class="row"><button class="btn ghost wide" data-act="tleave">나가기</button></div></section>`;const L=tPlayers(),host=r.host===FB.pid,playing=r.st==='play',inn=tMeIn();return `<section><h2>👥 단어 소나기 단체전</h2><p class="sub">방 코드 <b>${esc(RM.id)}</b> · ${L.length}/${TMAX}명 · 90초 · Lv.2 단어</p><div class="card">${L.length?L.map(p=>`<div class="wrow" style="padding:4px 0"><span class="grow">${esc(p.n)}${p.id===FB.pid?' (나)':''}</span>${p.id===r.host?'<span class="bdg ok">방장</span>':''}</div>`).join(''):'<p class="note">아직 아무도 없어요</p>'}</div>${playing&&!inn?`<div class="card note">지금 게임이 진행 중이에요. 다음 판부터 같이 할 수 있어요.</div>`:''}${!playing&&!inn&&L.length>=TMAX?`<div class="card note">방이 꽉 찼어요 (최대 ${TMAX}명).</div>`:''}<div class="card note">단어마다 가장 빨리 맞힌 <b>1등 5점 · 2등 3점 · 3등 1점</b>. 틀리면 그 단어는 끝이에요. 영어→뜻, 뜻→영어가 섞여 나와요. 판이 끝나면 1·2·3등에게 <b>이번 주 단체전 리그 점수</b> 5·3·1점!</div><div class="row"><button class="btn ghost grow" data-act="tinv">카톡으로 초대</button>${host?`<button class="btn grow" data-act="tstart" ${L.length<2||playing?'disabled':''}>${L.length<2?'2명부터 시작':'시작하기'}</button>`:''}</div>${host?'':'<p class="note" style="text-align:center">방장이 시작하면 바로 시작돼요.</p>'}${tChatBox()}<div class="row"><button class="btn ghost wide" data-act="tleave">방 나가기</button></div></section>`+(setTimeout(tChatRestore,0),'')}
async function loadLeague(force){if(!FB||lgBusy)return;if(!force&&lgData&&Date.now()-lgAt<60000)return;lgBusy=true;try{const sn=await FB.fs.getDoc(FB.fs.doc(FB.db,'leagues',weekStart(today())));lgData=sn.exists()?sn.data():{}}catch(e){lgData=lgData||{}}lgAt=Date.now();lgBusy=false;render()}
function leagueHTML(){const L=Object.entries(lgData||{}).filter(([,v])=>v&&typeof v==='object').map(([id,v])=>({id,n:String(v.n||'친구').slice(0,12),p:v.p|0,g:v.g|0,w:v.w|0,tt:typeof v.tt==='string'?v.tt:''})).sort((a,b)=>b.p-a.p||b.w-a.w||a.g-b.g).slice(0,20);return `<section><h2>👥 이번 주 단체전 리그</h2><p class="sub">단체전에서 1등 5점, 2등 3점, 3등 1점이 쌓여요. 매주 월요일에 새로 시작해요.</p><div class="card">${lgData==null?'<p class="note">불러오는 중…</p>':L.length?L.map((x,i)=>`<div class="gr${FB&&x.id===FB.pid?' meg':''}"><span class="n">${i+1}</span><span class="grow">${esc(x.n)}${x.tt?` <span class="ttl">${esc(x.tt)}</span>`:''}<div class="note">${x.g}판 · 1등 ${x.w}번</div></span><b>${x.p}점</b></div>`).join(''):'<p class="note">아직 이번 주 단체전 기록이 없어요. 게임 탭에서 방을 만들어 친구들을 불러보세요!</p>'}</div><div class="row"><button class="btn ghost wide" data-act="tgo">👥 단체전 방 만들러 가기</button></div></section>`}
